import{_ as n,a,c as o,ac as i}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点","description":"L49–L72 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点","description":"L49–L72 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-03/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 语法总结","summary":"L49–L72 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结","link":"/life/english/new-concept/book-2/unit-03/grammar"},"next":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-03/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结","link":"/life/english/new-concept/book-2/unit-03/grammar"},"next":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-03/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/grammar-part-01.md","filePath":"life/english/new-concept/book-2/unit-03/grammar-part-01.md"}'),s={name:"life/english/new-concept/book-2/unit-03/grammar-part-01.md"};function t(r,e,l,p,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-单元-3-语法总结-·-叙事中的时态与衔接至被动语态与信息重点" tabindex="-1">第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-语法总结-·-叙事中的时态与衔接至被动语态与信息重点" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 语法总结 · 叙事中的时态与衔接至被动语态与信息重点&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><h2 id="第二册-实践与进步-·-单元-3-语法总结" tabindex="-1">第二册：实践与进步 · 单元 3 语法总结 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-语法总结" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 语法总结 {#第二册-实践与进步-·-单元-3-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><h2 id="叙事中的时态与衔接" tabindex="-1">叙事中的时态与衔接 <a class="header-anchor" href="#叙事中的时态与衔接" aria-label="Permalink to &quot;叙事中的时态与衔接 {#叙事中的时态与衔接}&quot;">​</a></h2><p>综合叙事先建立时间线，再为每个动作选择观察角度：简单过去推进事件，过去进行交代背景，过去完成回顾更早动作。指代词应有清楚的前文对象，连接词应准确说明原因、转折或结果。并不是句子越长越好；一个句子包含多个时间层次时，应先写清主干，再添加从句。检查时分别核对事实顺序、主谓一致、动词形式和信息衔接。本课应用：was sleeping 交代风吹来时的背景；woke 表示突然醒来。叙事不必每句都写 then，可用时间从句连接重要转折。</p><p><strong>L49 原创例句：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><p>一阵风把毯子吹走时，我正睡在露台上。</p><p><strong>易错：</strong> blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">Lesson 49</a></p><h2 id="过去完成时与先后关系" tabindex="-1">过去完成时与先后关系 <a class="header-anchor" href="#过去完成时与先后关系" aria-label="Permalink to &quot;过去完成时与先后关系 {#过去完成时与先后关系}&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had passed 表下车之前已经经过目的地；did not realise 描述当时的认知。先后关系应靠时间线核对，不只看句子排列顺序。</p><p><strong>L50 原创例句：</strong> By the time I asked, the bus had passed my stop.</p><p>等我开口询问时，公交车已经驶过了我要下的站。</p><p><strong>易错：</strong> get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">Lesson 50</a></p><h2 id="完成进行时与持续活动" tabindex="-1">完成进行时与持续活动 <a class="header-anchor" href="#完成进行时与持续活动" aria-label="Permalink to &quot;完成进行时与持续活动 {#完成进行时与持续活动}&quot;">​</a></h2><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：has been avoiding 强调持续到目前的行为；has avoided three snacks 强调次数。所谓奖励不等于健康建议，这里只练习语言表达。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：had been planting 是过去参照点之前一直进行的活动；与 have been planting 的参照点在现在不同。需要明确过去的停顿或报告时刻。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：has been leaking 强调持续泄漏及当前痕迹；has leaked a litre 强调量。两者都不自动说明泄漏此刻仍在继续，要看上下文。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：have been monitoring 表持续工作；have recorded three changes 则是成果数量。观察资料可支持判断，但不等于精确预知每次喷发。</p><p><strong>L51 原创例句：</strong> Tess has been avoiding sweet snacks for two weeks.</p><p>苔丝两周来一直尽量不吃甜食。</p><p><strong>L62 原创例句：</strong> The volunteers had been planting seeds for hours when the rain began.</p><p>下雨时，志愿者已经连续播种数小时了。</p><p><strong>L66 原创例句：</strong> A jar of honey has been leaking inside the delivery van.</p><p>一罐蜂蜜一直在送货车内渗漏。</p><p><strong>L67 原创例句：</strong> The scientists have been monitoring the volcano since March.</p><p>科学家们自三月以来一直在监测这座火山。</p><p><strong>易错：</strong> since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p><p>had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p><p>honey have been 错误；这里主语 a jar of honey 的核心是 jar，配 has。</p><p>since three months 不合常用表达；用 for three months 或 since March。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">Lesson 51</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-062">Lesson 62</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-066">Lesson 66</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-067">Lesson 67</a></p><h2 id="现在完成时与过去时间" tabindex="-1">现在完成时与过去时间 <a class="header-anchor" href="#现在完成时与过去时间" aria-label="Permalink to &quot;现在完成时与过去时间 {#现在完成时与过去时间}&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：have covered 指到现在形成覆盖结果；have been falling 强调落叶过程。表达满地叶子不等于每一片都来自同一棵树。</p><p><strong>L52 原创例句：</strong> Fallen leaves have covered the path outside our classroom.</p><p>落叶已经覆盖了教室外的小路。</p><p><strong>易错：</strong> leaves 是 leaf 的复数；不能写 leafs 来表示这里的树叶。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">Lesson 52</a></p><h2 id="被动语态与信息重点" tabindex="-1">被动语态与信息重点 <a class="header-anchor" href="#被动语态与信息重点" aria-label="Permalink to &quot;被动语态与信息重点 {#被动语态与信息重点}&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was caused by 指向原因，但只有调查结果支持时才能这样断言；may have been caused by 则保留不确定性，语气不同。</p><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will have been tested 表未来某点之前测试完成，区别于 will be tested 仅说将进行测试。不要把预计完成写成已经完成。</p><p><strong>L53 原创例句：</strong> The power failure was caused by a damaged wire.</p><p>这次停电是由一根损坏的电线引起的。</p><p><strong>L61 原创例句：</strong> By Friday, the replacement camera will have been tested twice.</p><p>到周五之前，替换摄像机将完成两次测试。</p><p><strong>易错：</strong> caused from 不合常见搭配；被动原因用 caused by。</p><p>will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">Lesson 53</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-061">Lesson 61</a></p>',51)])])}const f=n(s,[["render",t]]);export{d as __pageData,f as default};
